#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=9

# Run from the project, even when invoked from another directory.
local setup_root setup_ci_run setup_ci_result setup_ci_pending=0
setup_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)
cd -- "$setup_root"
ENV_FILE="$setup_root/.env.local"
export GH_REPO=Lomzem/budge
umask 077

for setup_tool in bun node git gh; do
  command -v "$setup_tool" >/dev/null 2>&1 || {
    warn "Install $setup_tool before running this wizard."
    return 1
  }
done
[[ -t 0 ]] || { warn "Run this script in an interactive terminal."; return 1; }
[[ ! -L "$ENV_FILE" ]] || { warn ".env.local must be a regular file."; return 1; }
git check-ignore -q .env.local || { warn ".env.local must be gitignored."; return 1; }
if [[ -n "$(git ls-files -- .env.local)" ]]; then
  warn ".env.local is tracked. Remove it from Git before saving credentials."
  return 1
fi
[[ ! -f "$ENV_FILE" ]] || chmod 600 "$ENV_FILE"
gh auth status >/dev/null 2>&1 || { warn "Run gh auth login, then rerun this wizard."; return 1; }
gh repo view "$GH_REPO" --json nameWithOwner >/dev/null || return 1

banner "Budge local development and CI setup"
note "This configures the existing local backend and GitHub repository $GH_REPO."
note "Clerk credentials stay in ignored .env.local and GitHub Actions secrets."
note "Keep a copy of the Clerk secret key in your password manager."
if [[ "$(node -p 'process.versions.node.split(".")[0]')" != 24 ]]; then
  warn "This shell uses $(node --version). The repo and CI target Node 24."
  note "Use Node 24 in your development terminals to match CI."
fi
pause

stage "Enable GitHub and email on the development app"
open_url "https://dashboard.clerk.com/"
step "Create a Budge application, or select the existing Budge application."
step "Select its Development instance. Keep that instance selected throughout."
open_url "https://dashboard.clerk.com/~/user-authentication/sso-connections"
step "If GitHub is absent, select Add connection, For all users, then GitHub."
step "Enable GitHub for sign-up and sign-in. Development uses Clerk's shared OAuth app."
step "Disable any other social providers you enabled."
open_url "https://clerk.com/docs/guides/configure/auth-strategies/sign-up-sign-in-options"
step "In Budge's Development instance, open User & authentication, then Email."
step "Enable Email and email verification codes. Keep Email enabled for the CI user's address."
step "Keep Password disabled. Disable phone and username sign-in if enabled."
pause "Press Enter when GitHub and Email are enabled on the Development instance."

stage "Save the Clerk development keys"
open_url "https://dashboard.clerk.com/last-active?path=api-keys"
step "Check that Development is selected. Copy the Publishable key from API keys."
while true; do
  ask PUBLIC_CLERK_PUBLISHABLE_KEY "Publishable key, starting pk_test_:"
  [[ "$PUBLIC_CLERK_PUBLISHABLE_KEY" =~ ^pk_test_[A-Za-z0-9_=-]+$ ]] && break
  warn "Use a development publishable key, starting pk_test_."
done
step "Reveal and copy the development Secret key on the same page."
while true; do
  ask_secret CLERK_SECRET_KEY "Secret key, starting sk_test_, input hidden:"
  [[ "$CLERK_SECRET_KEY" =~ ^sk_test_[A-Za-z0-9_]+$ ]] && break
  warn "Use a development secret key, starting sk_test_."
done
write_env PUBLIC_CLERK_PUBLISHABLE_KEY "$PUBLIC_CLERK_PUBLISHABLE_KEY"
write_env CLERK_SECRET_KEY "$CLERK_SECRET_KEY"
export PUBLIC_CLERK_PUBLISHABLE_KEY CLERK_SECRET_KEY
say "Saved both keys to .env.local with permissions 600."
pause

stage "Activate the Convex integration"
open_url "https://dashboard.clerk.com/apps/setup/convex"
step "Select Budge's Development instance and activate the Convex integration."
step "Copy the Frontend API URL, including https://."
note "Use the integration, since this app requests the standard Clerk session token."
note "A JWT template alone does not add the audience to that token."
while true; do
  ask CLERK_JWT_ISSUER_DOMAIN "Frontend API URL, https://...clerk.accounts.dev:"
  CLERK_JWT_ISSUER_DOMAIN="${CLERK_JWT_ISSUER_DOMAIN%/}"
  export CLERK_JWT_ISSUER_DOMAIN
  if bun -e '
    const expected = "https://" + Buffer.from(process.env.PUBLIC_CLERK_PUBLISHABLE_KEY.slice(8), "base64").toString("utf8").replace(/\$$/, "");
    const issuer = process.env.CLERK_JWT_ISSUER_DOMAIN;
    if (issuer !== expected || !/^https:\/\/[a-z0-9-]+\.clerk\.accounts\.dev$/.test(issuer)) process.exit(1);
  '; then break; fi
  warn "The URL must match the development instance encoded in your publishable key."
done
write_env CLERK_JWT_ISSUER_DOMAIN "$CLERK_JWT_ISSUER_DOMAIN"
pause

stage "Sign in as the owner"
open_url "https://dashboard.clerk.com/~/account-portal"
step "Use the visit button beside Sign-in to open this instance's hosted sign-in page."
step "Sign in with GitHub or email. If you already have a Clerk user, reuse it."
note "If this app is already Invite-only, invite your verified email from Users first."
pause "Press Enter once you have signed in."
open_url "https://dashboard.clerk.com/~/users"
step "Open your user and copy its User ID, starting user_."
while true; do
  ask BUDGE_OWNER_SUBJECT "Your Clerk User ID for the local backend:"
  [[ "$BUDGE_OWNER_SUBJECT" =~ ^user_[A-Za-z0-9]+$ ]] && break
  warn "Copy the User ID, starting user_."
done
export BUDGE_OWNER_SUBJECT
if ! bun -e '
  try {
    const r = await fetch("https://api.clerk.com/v1/users/" + encodeURIComponent(process.env.BUDGE_OWNER_SUBJECT), {
      headers: { Authorization: "Bearer " + process.env.CLERK_SECRET_KEY }, signal: AbortSignal.timeout(15000)
    });
    if (!r.ok) { console.error("Clerk could not verify that user with this secret key. HTTP " + r.status); process.exit(1); }
    const user = await r.json();
    if (user.id !== process.env.BUDGE_OWNER_SUBJECT) {
      console.error("Clerk returned a different user ID. Check the selected owner."); process.exit(1);
    }
  } catch { console.error("Could not reach Clerk. Check your connection and rerun the wizard."); process.exit(1); }
'; then return 1; fi
write_env BUDGE_OWNER_SUBJECT "$BUDGE_OWNER_SUBJECT"
pause

stage "Restrict sign-up"
open_url "https://dashboard.clerk.com/~/user-authentication/access-mode"
step "Select Invite-only and Save. Your existing owner user can still sign in."
note "Leave GitHub and Email enabled. Invite-only controls who can create an account."
note "CI uses a backend sign-in token and does not need email codes or passwords."
pause "Press Enter when the instance is Invite-only with GitHub and Email enabled."

stage "Create the one CI test user"
open_url "https://dashboard.clerk.com/~/users"
say "You choose the CI email. Clerk does not generate it, and no mailbox is needed."
note "Use budge-ci+clerk_test@example.com, or reuse your existing CI user's exact email."
while true; do
  ask E2E_CLERK_USER_EMAIL "CI email, Enter uses budge-ci+clerk_test@example.com:"
  E2E_CLERK_USER_EMAIL="${E2E_CLERK_USER_EMAIL:-budge-ci+clerk_test@example.com}"
  [[ "$E2E_CLERK_USER_EMAIL" =~ ^[A-Za-z0-9._+%-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]] && break
  warn "Enter a full email address for the test user."
done
step "Choose Create user once and enter this email: $E2E_CLERK_USER_EMAIL"
step "If the test user already exists without an email, add this address to its profile instead."
note "If Clerk shows no email field, enable Email under User & authentication, then return here."
note "Keep this user separate from your owner. No CI password is needed."
step "Open the saved test user and copy its User ID, starting user_."
while true; do
  ask E2E_CLERK_USER_ID "CI test user's User ID:"
  [[ "$E2E_CLERK_USER_ID" =~ ^user_[A-Za-z0-9]+$ && "$E2E_CLERK_USER_ID" != "$BUDGE_OWNER_SUBJECT" ]] && break
  warn "Use the separate CI user's ID, starting user_."
done
export E2E_CLERK_USER_ID E2E_CLERK_USER_EMAIL
if ! bun -e '
  try {
    const r = await fetch("https://api.clerk.com/v1/users/" + encodeURIComponent(process.env.E2E_CLERK_USER_ID), {
      headers: { Authorization: "Bearer " + process.env.CLERK_SECRET_KEY }, signal: AbortSignal.timeout(15000)
    });
    if (!r.ok) { console.error("Clerk could not verify the CI user. HTTP " + r.status); process.exit(1); }
    const user = await r.json();
    if (!user.email_addresses?.some(e => e.email_address === process.env.E2E_CLERK_USER_EMAIL)) {
      console.error("That email does not belong to the selected CI user."); process.exit(1);
    }
  } catch { console.error("Could not reach Clerk. Check your connection and rerun the wizard."); process.exit(1); }
'; then return 1; fi
write_env E2E_CLERK_USER_ID "$E2E_CLERK_USER_ID"
write_env E2E_CLERK_USER_EMAIL "$E2E_CLERK_USER_EMAIL"
pause

stage "Configure the local Convex backend"
local setup_deployment
setup_deployment=$(_existing CONVEX_DEPLOYMENT || true)
case "$setup_deployment" in
  anonymous:*|local:*) ;;
  *) warn "Expected an existing local Convex deployment in .env.local. Stop here and check it."; return 1 ;;
esac
say "Open another terminal in this project and leave this command running:"
say "  bun run dev:backend"
note "The first push can fail until this stage sets the two required backend variables."
pause "Press Enter when the local backend is running."
# Explicit local selection keeps these writes on this checkout's local backend.
bunx convex env set --deployment local CLERK_JWT_ISSUER_DOMAIN "$CLERK_JWT_ISSUER_DOMAIN"
bunx convex env set --deployment local BUDGE_OWNER_SUBJECT "$BUDGE_OWNER_SUBJECT"
say "Wait for 'Convex functions ready' in the backend terminal."
pause "Press Enter once Convex reports that its functions are ready."

stage "Set the GitHub Actions secrets"
open_url "https://github.com/Lomzem/budge/settings/secrets/actions"
say "The wizard will create or replace exactly these five repository secrets:"
say "  CLERK_DEV_PUBLISHABLE_KEY, CLERK_DEV_SECRET_KEY, CLERK_DEV_JWT_ISSUER_DOMAIN"
say "  E2E_CLERK_USER_ID, E2E_CLERK_USER_EMAIL"
note "GitHub supplies GITHUB_TOKEN automatically. This workflow needs no Convex deploy key."
if confirm "Write these five development secrets to Lomzem/budge?"; then
  set_secret CLERK_DEV_PUBLISHABLE_KEY "$PUBLIC_CLERK_PUBLISHABLE_KEY"
  set_secret CLERK_DEV_SECRET_KEY "$CLERK_SECRET_KEY"
  set_secret CLERK_DEV_JWT_ISSUER_DOMAIN "$CLERK_JWT_ISSUER_DOMAIN"
  set_secret E2E_CLERK_USER_ID "$E2E_CLERK_USER_ID"
  set_secret E2E_CLERK_USER_EMAIL "$E2E_CLERK_USER_EMAIL"
else
  SKIPPED+=("Upload the five Clerk development secrets to Lomzem/budge.")
fi
pause

stage "Check local sign-in"
say "Keep the backend running. In another terminal in this project, run:"
say "  bun run dev --port 5173 --strictPort"
pause "Press Enter when Vite is ready on port 5173."
open_url "http://localhost:5173/sign-in"
step "Sign in with GitHub or email as your owner user and check that the Budget screen opens."
if ! confirm "Does your owner account reach the Budget screen?"; then
  SKIPPED+=("Verify local owner sign-in. Check both dev terminal logs.")
fi
open_url "https://github.com/Lomzem/budge/actions"
setup_ci_run=$(gh run list --repo "$GH_REPO" --workflow ci.yml \
  --commit "$(git rev-parse HEAD)" --limit 1 --json databaseId \
  --jq '.[0].databaseId // empty' 2>/dev/null || true)
if [[ -z "$setup_ci_run" ]]; then
  setup_ci_pending=1
  say "There is no CI run for this commit yet. Your setup values are saved."
  note "CI runs when a pull request is opened or updated, or when main receives a push."
  note "Pushing this feature branch without a pull request does not trigger CI."
else
  setup_ci_result=$(gh run view "$setup_ci_run" --repo "$GH_REPO" --json jobs \
    --jq '[.jobs[] | select(.name == "e2e")] | .[0].conclusion // "pending"' 2>/dev/null || true)
  if [[ "$setup_ci_result" == success ]]; then
    say "The e2e job passed for this commit."
  elif [[ -z "$setup_ci_result" || "$setup_ci_result" == pending ]]; then
    setup_ci_pending=1
    say "CI verification is pending. Check the e2e job when the run finishes."
  else
    SKIPPED+=("The e2e job concluded with $setup_ci_result. Inspect CI run $setup_ci_run.")
  fi
fi

finish
if (( ${#SKIPPED[@]} )); then
  say "Setup still has unfinished steps listed above. Rerun this wizard to finish them."
  return 1
fi
say "Local development and CI secrets are configured. Keep both dev terminals running while working."
if (( setup_ci_pending )); then
  say "CI verification is pending. You do not need to rerun this wizard for that."
fi
say "Production and preview hosting belong to ticket 04. Plaid setup comes with bank sync."
}

run_wizard "$@"; exit
